import{_ as a,o as i,c as o,ae as s}from"./chunks/framework.FQ5RHm_v.js";const m=JSON.parse('{"title":"wvke-sdk | Personalização Perfeita!","titleTemplate":false,"description":"","frontmatter":{"title":"wvke-sdk | Personalização Perfeita!","titleTemplate":false},"headers":[],"relativePath":"pt/index.md","filePath":"pt/index.md"}'),t={name:"pt/index.md"};function l(r,e,d,n,c,p){return i(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="wvke-sdk" tabindex="-1">wvke-sdk <a class="header-anchor" href="#wvke-sdk" aria-label="Permalink to &quot;wvke-sdk&quot;">​</a></h1><p>wvke-sdk é um SDK JavaScript para comunicação com periféricos gamer, incluindo teclados e mouses.</p><p>Construído sobre a moderna tecnologia WebHID, permite personalização profunda e controle inteligente de teclados, mouses e outros periféricos. Acelera a entrega de produtos periféricos gamer e abre novas possibilidades no ecossistema gamer. O projeto é desenvolvido e mantido pelo GDE Game Driver Engine Team.</p><h2 id="tipos-de-sdk" tabindex="-1">Tipos de SDK <a class="header-anchor" href="#tipos-de-sdk" aria-label="Permalink to &quot;Tipos de SDK&quot;">​</a></h2><h3 id="⌨️-teclado-linear" tabindex="-1">⌨️ Teclado Linear <a class="header-anchor" href="#⌨️-teclado-linear" aria-label="Permalink to &quot;⌨️ Teclado Linear&quot;">​</a></h3><p>Construído para teclados mecânicos:</p><ul><li>Mapeamento de teclas e troca de camada</li><li>Controle de iluminação RGB</li><li>Autorização WebHID, lista de dispositivos autorizados e inicialização</li><li>Interruptor de curso completo RT, ajuste de curso e zona segura</li><li>Gravação e reprodução de macros</li><li>Ajuste de taxa de polling (1KHz-8KHz)</li><li>Troca de modo de sistema (Windows/Mac)</li></ul><h3 id="🖱️-sdk-mouse" tabindex="-1">🖱️ SDK Mouse <a class="header-anchor" href="#🖱️-sdk-mouse" aria-label="Permalink to &quot;🖱️ SDK Mouse&quot;">​</a></h3><p>Construído para mouses gamer:</p><ul><li>Ajuste DPI (400-16000 DPI)</li><li>Programação de botões e macros</li><li>Personalização de iluminação RGB</li><li>Ajuste de distância de levantamento</li><li>Otimização de polling</li></ul><h2 id="caracteristicas" tabindex="-1">Características <a class="header-anchor" href="#caracteristicas" aria-label="Permalink to &quot;Características&quot;">​</a></h2><ul><li>Suporte moderno a JavaScript/TypeScript</li><li>Comunicação de hardware WebHID</li><li>APIs completas de controle de iluminação</li><li>APIs de mapeamento de teclas e macros</li><li>APIs de curso RT, teclas avançadas e inicialização</li><li>APIs DPI e mapeamento de botões de mouse</li><li>Serviço de atualização personalizada geral</li><li>Documentação API detalhada</li></ul><h2 id="tutorial" tabindex="-1">Tutorial <a class="header-anchor" href="#tutorial" aria-label="Permalink to &quot;Tutorial&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wvke-sdk</span></span></code></pre></div><p>Consulte a <a href="/wvke.sdkdoc/docs/pt/api/info.html">documentação da API</a> para mais detalhes.</p>',15)])])}const h=a(t,[["render",l]]);export{m as __pageData,h as default};
